// Some portions generated by Codex
package org.eclipse.rdf4j.http.server;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mockStatic;

import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;
import org.slf4j.MDC;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

class ServerInterceptorLoggingContextTest {

	@Test
	void requestIdentifierSurvivesWithoutAnMdcProvider() throws Exception {
		ServerInterceptor interceptor = new ServerInterceptor() {
			@Override
			protected String getThreadName() {
				return "query-request";
			}
		};
		MockHttpServletRequest first = new MockHttpServletRequest();
		MockHttpServletRequest second = new MockHttpServletRequest();
		MockHttpServletResponse response = new MockHttpServletResponse();
		String threadName = Thread.currentThread().getName();
		try (MockedStatic<MDC> noMdcProvider = mockStatic(MDC.class)) {
			try {
				interceptor.preHandle(first, response, this);
				assertThat(first.getAttribute("org.eclipse.rdf4j.requestId")).isInstanceOf(String.class)
						.asString()
						.startsWith("process:")
						.contains(":request:");
			} finally {
				interceptor.afterCompletion(first, response, this, null);
			}
			try {
				interceptor.preHandle(second, response, this);
				assertThat(second.getAttribute("org.eclipse.rdf4j.requestId"))
						.isNotNull()
						.isNotEqualTo(first.getAttribute("org.eclipse.rdf4j.requestId"));
			} finally {
				interceptor.afterCompletion(second, response, this, null);
			}
		}
		assertThat(Thread.currentThread().getName()).isEqualTo(threadName);
	}
}
